"module m(input logic [1:0] a, output logic y);
  assign y = a;
endmodule
"

"module m(input logic a, input logic [1:0] b, output logic y);
  assign y = a & b;
endmodule
"

"module m(input logic a, output logic y);
  always_comb y = a;
endmodule
"

"module m(input logic a, output logic y);
  assign y = 2'b11;
endmodule
"
